11	
12	import java.util.Collection;
13	import java.util.List;
14	import java.util.Map;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName",
23	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    /** Fixed city-to-region table used to derive an owner's locality. */
30	    Map<String, String> CITY_REGION = Map.of(
31	        "Sydney", "NSW",
32	        "Melbourne", "VIC",
33	        "Brisbane", "QLD");
34	
35	    /**
36	     * The canonical region derived from the owner's city using the fixed
37	     * {@link #CITY_REGION} table, or 'UNKNOWN' when the city is not listed.
38	     */
39	    default String locality(Owner owner) {
40	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
41	    }
42	
43	    /**
44	     * The owner's membership tier: 'SILVER' when namesakeCount is 0 and an email
45	     * address is present, otherwise 'BRONZE'.
46	     */
47	    default String membershipTier(Owner owner) {
48	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
49	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
50	        return uniqueName && hasEmail ? "SILVER" : "BRONZE";
51	    }
52	
53	    /**
54	     * The upper-cased first letters of firstName and lastName, dot-separated with a
55	     * trailing dot, e.g. 'J.S.'.
56	     */
57	    default String initials(Owner owner) {
58	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
59	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
60	    }
61	
62	    Owner toOwner(OwnerDto ownerDto);
63	
64	    @Mapping(target = "id", ignore = true)
65	    @Mapping(target = "pets", ignore = true)
66	    Owner toOwner(OwnerFieldsDto ownerDto);
67	
68	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
69	
70	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
71	
72	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
73	        OwnerPageDto ownerPageDto = new OwnerPageDto();
74	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
75	        ownerPageDto.setPage(ownerPage.getNumber());
76	        ownerPageDto.setSize(ownerPage.getSize());
77	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
78	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
79	        return ownerPageDto;
80	    }
81	}
