204	    /**
205	     * Normalize a value for household-identity comparison: null becomes an empty
206	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
207	     * to a single space, and the result is lower-cased.
208	     */
209	    private static String normalizeIdentity(String value) {
210	        if (value == null) {
211	            return "";
212	        }
213	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
214	    }
215	
216	    /**
217	     * Build the stable, shared household identifier for an owner, formatted
218	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
219	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
220	     * Owners in the same household (same normalized lastName and address) therefore
221	     * derive an identical householdId.
222	     */
223	    private static String householdId(String lastNameKey, String addressKey) {
224	        String source = lastNameKey + "|" + addressKey;
225	        try {
226	            byte[] digest = MessageDigest.getInstance("SHA-256")
227	                .digest(source.getBytes(StandardCharsets.UTF_8));
228	            StringBuilder sb = new StringBuilder(digest.length * 2);
229	            for (byte b : digest) {
230	                sb.append(String.format("%02x", b));
231	            }
232	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
233	        }
234	        catch (NoSuchAlgorithmException e) {
235	            throw new IllegalStateException("SHA-256 not available", e);
236	        }
237	    }
238	
239	    /**
240	     * Build the customer code assigned on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}:
241	     * CITY3 is the upper-cased first three letters of {@code city}, LAST3 is the upper-cased
242	     * first three letters of {@code lastName} and NNNN is a per-city 4-digit zero-padded
243	     * sequence equal to one more than the number of owners already in that city
244	     * (e.g. 'LON-SMI-0007').
245	     */
246	    private String nextCustomerCode(String city, String lastName) {
247	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
248	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
249	        String cityKey = normalizeIdentity(city);
250	        int sequence = (int) this.clinicService.findAllOwners().stream()
251	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
252	            .count() + 1;
253	        return String.format("%s-%s-%04d", city3, last3, sequence);
254	    }
