216	    /**
217	     * Build the stable, shared household identifier for an owner, formatted
218	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
219	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
220	     * Owners in the same household (same normalized lastName and address) therefore
221	     * derive an identical householdId.
222	     */
223	    private static String householdId(String lastNameKey, String addressKey) {
224	        String source = lastNameKey + "|" + addressKey;
225	        try {
226	            byte[] digest = MessageDigest.getInstance("SHA-256")
227	                .digest(source.getBytes(StandardCharsets.UTF_8));
228	            StringBuilder sb = new StringBuilder(digest.length * 2);
229	            for (byte b : digest) {
230	                sb.append(String.format("%02x", b));
231	            }
232	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
233	        }
234	        catch (NoSuchAlgorithmException e) {
235	            throw new IllegalStateException("SHA-256 not available", e);
236	        }
237	    }
