256	    /**
257	     * Roll a registration date forward to the next business day: a Saturday or Sunday
258	     * advances to the following Monday, and a weekday is returned unchanged.
259	     */
260	    private static LocalDate toBusinessDay(LocalDate date) {
261	        return switch (date.getDayOfWeek()) {
262	            case SATURDAY -> date.plusDays(2);
263	            case SUNDAY -> date.plusDays(1);
264	            default -> date;
